# 36 interior design brands: (slug, name, url, verified fact, observation 1, observation 2, slide notes)
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
# Interior design studios
("kelly-wearstler","Kelly Wearstler","https://www.kellywearstler.com/","Kelly Wearstler founded her Los Angeles studio in 1995.","Heavy, extra-wide capitals set the full name on one line.","The bold, confident type matches a designer known for daring, sculptural interiors."),
("studio-mcgee","Studio McGee","https://studio-mcgee.com/","Shea and Syd McGee founded Studio McGee in Utah in 2014.","Thin, widely spaced capitals feel light and calm.","A small raised c in McGee is the one detail that makes the wordmark feel custom."),
("yabu-pushelberg","Yabu Pushelberg","https://www.yabupushelberg.com/","George Yabu and Glenn Pushelberg founded the studio in Toronto in 1980.","Rounded lowercase letters make two long surnames feel soft and friendly.","The logo uses only the founders' names, which suits a studio known for its partners."),
("rockwell-group","Rockwell Group","https://rockwellgroup.com/","David Rockwell founded Rockwell Group in New York in 1984.","Heavy lowercase letters run the two words together.","Joining rockwell and group into one word makes the name read like a single mark."),
("pierre-yovanovitch","Pierre Yovanovitch","https://www.pierreyovanovitch.com/","Pierre Yovanovitch opened his Paris studio in 2001 after working in fashion with Pierre Cardin.","The logo is just his initials, P and Y, in heavy geometric capitals.","A wide gap between the two letters gives the monogram space, like a gallery wall."),
("india-mahdavi","India Mahdavi","https://india-mahdavi.com/","India Mahdavi opened her studio in Paris in 1999.","A clean lowercase sans serif sets her first and last name.","The plain type lets her colourful interiors and furniture do the talking."),
("ken-fulk","Ken Fulk","https://www.kenfulk.com/","Ken Fulk runs a design and events studio based in San Francisco.","Tall, condensed capitals look like a theatre poster.","Tight spacing makes the short name feel bold and dramatic."),
("commune-design","Commune Design","https://communedesign.com/","Commune was founded in Los Angeles in 2004 by Roman Alonso, Steven Johanknecht and siblings Pamela and Ramin Shamshiri.","A deep red lowercase wordmark is the only colour among the studio logos.","Round, repeating letters give the word commune a warm, communal rhythm."),
("workstead","Workstead","https://workstead.com/","Robert Highsmith and Stefanie Brechbuehler founded Workstead in Brooklyn in 2009.","Tall, condensed capitals feel like signage on an old workshop.","One heavy word, with no symbol, suits a studio known for craft and lighting."),
# Furniture brands
("rh","RH","https://rh.com/","Restoration Hardware was founded in Eureka, California, in 1979 and now trades as RH.","Two tall serif capitals with very thin and very thick strokes.","The high contrast makes two letters look as expensive as a fashion house."),
("west-elm","West Elm","https://www.westelm.com/","West Elm opened in Brooklyn in 2002 and is owned by Williams-Sonoma.","Light lowercase letters are spaced widely.","The relaxed, airy type matches mid-century style furniture for city apartments."),
("cb2","CB2","https://www.cb2.com/","Crate & Barrel launched CB2 in Chicago in 2000.","Wide capitals sit inside a thin rectangular box.","The box works like a label, which suits a brand born as a spin-off."),
("article","Article","https://www.article.com/","Article was founded in Vancouver in 2013 and sells furniture online.","Widely spaced grey capitals feel calm and modern.","A coral full stop is the only colour and turns a common word into a brand."),
("hay","HAY","https://www.hay.com/","Rolf and Mette Hay founded HAY in Copenhagen in 2002.","Three heavy black capitals make one of the shortest names here.","The plain, bold type lets colourful products carry the personality."),
("vitra","Vitra","https://www.vitra.com/en-us/home","Vitra was founded in Switzerland in 1950 and produces designs by Charles and Ray Eames.","Bold lowercase letters end with a full stop.","The heavy, compact word feels engineered, which fits a company known for chairs."),
("knoll","Knoll","https://www.knoll.com/","Knoll was founded in New York in 1938 and is now part of MillerKnoll.","Very heavy letters in orange-red are set tightly together.","The strong colour makes the short name stand out in showrooms and catalogues."),
("herman-miller","Herman Miller","https://www.hermanmiller.com/","The company took the name Herman Miller in Zeeland, Michigan, in 1923 and is now part of MillerKnoll.","A bold red M symbol sits before the name.","The full name in the same red joins the two words without a space."),
("design-within-reach","Design Within Reach","https://www.dwr.com/","Rob Forbes founded Design Within Reach in 1998, and it is now part of MillerKnoll.","White initials sit at the bottom of a solid black square.","The DWR box works as a stamp on catalogues, stores and shopping bags."),
# Design marketplaces and services
("houzz","Houzz","https://www.houzz.com/","Adi Tatarko and Alon Cohen founded Houzz in Palo Alto in 2009.","A green h mark is shaped like a simple house.","Rounded lowercase letters make the platform feel friendly and approachable."),
("havenly","Havenly","https://havenly.com/","Lee Mayer and Emily Motayed founded Havenly in Denver in 2014.","Thin, wide serif capitals look elegant and traditional.","The classic type makes an online service feel like a high-end studio."),
("decorilla","Decorilla","https://www.decorilla.com/","Decorilla is an online interior design service that matches clients with designers.","A square mark looks like a window frame or a floor plan.","Thin capitals beside it keep the logo clean and light."),
("1stdibs","1stDibs","https://www.1stdibs.com/","1stDibs started in 2001 as an online catalogue of dealers at the Paris flea market.","A stacked st sits beside the 1, like a raised ordinal on an old price tag.","Classic serif capitals suit a marketplace for antiques and luxury design."),
("chairish","Chairish","https://www.chairish.com/","Anna and Gregg Brockway founded Chairish in San Francisco in 2013.","A red brush script spells the name with a long swash on the h.","The handwriting style makes a marketplace feel personal, like a shop owner's sign."),
("wayfair","Wayfair","https://www.wayfair.com/","Niraj Shah and Steve Conine founded the company in Boston in 2002.","A purple pinwheel mark sits before the name.","Rounded lowercase letters in the same purple make the brand feel friendly and mass-market."),
("burrow","Burrow","https://burrow.com/","Burrow was founded in New York in 2017 and sells modular sofas online.","Wide, geometric grey capitals feel calm and modern.","The round letters echo soft furniture shapes."),
("floyd","Floyd","https://floydhome.com/","Floyd was founded in Detroit in 2014, starting with a table leg that clamps onto any surface.","Heavy black capitals make the short name feel solid.","The industrial type suits a brand built around simple, sturdy furniture."),
("lulu-and-georgia","Lulu and Georgia","https://www.luluandgeorgia.com/","Sara Sugarman founded Lulu and Georgia in Los Angeles in 2012.","Widely spaced capitals set the two names far apart.","A tiny AND tied with a small red bow sits between them."),
# Paint, materials and lighting
("tom-dixon","Tom Dixon","https://www.tomdixon.net/en_us/","Tom Dixon launched his own design brand in London in 2002.","The name is stacked in heavy, slightly quirky letters.","A full stop at the end gives the logo a confident, final feel."),
("benjamin-moore","Benjamin Moore","https://www.benjaminmoore.com/en-us","Benjamin Moore was founded in Brooklyn in 1883 and is owned by Berkshire Hathaway.","A black triangle with an M inside sits before the name.","Bold sans serif letters make the paint brand easy to read on cans and in stores."),
("sherwin-williams","Sherwin-Williams","https://www.sherwin-williams.com/","Sherwin-Williams was founded in Cleveland in 1866.","Blue italic capitals lean forward over two lines.","The wordmark is often paired with the brand's Cover the Earth globe."),
("schumacher","Schumacher","https://fschumacher.com/","Frederic Schumacher founded the fabric house in New York in 1889.","Classic serif capitals are spaced evenly across the name.","The traditional type suits a brand known for archive wallpapers and fabrics."),
("flos","Flos","https://flos.com/","Flos was founded in Merano, Italy, in 1962.","Tall, thin serif capitals with very fine details.","Four letters look like they were drawn with a light, precise pen, which suits a lighting brand."),
("louis-poulsen","Louis Poulsen","https://www.louispoulsen.com/en-us","Louis Poulsen was founded in Copenhagen in 1874 and is known for Poul Henningsen's PH lamps.","Heavy lowercase letters set both words close together.","The rounded letters feel warm, like the glow of its lamps."),
("artemide","Artemide","https://www.artemide.com/en","Ernesto Gismondi and Sergio Mazza founded Artemide in Milan in 1960.","A heavy red slab serif makes the name bold and dramatic.","The strong colour and weight stand out among quieter design brands."),
("kvadrat","Kvadrat","https://www.kvadrat.dk/en","Kvadrat was founded in Ebeltoft, Denmark, in 1968.","Heavy lowercase letters make one solid word.","The name means square in Danish, and the compact block of letters echoes it."),
("fireclay-tile","Fireclay Tile","https://www.fireclaytile.com/","Fireclay Tile was founded in California in 1986 and makes tile from recycled materials.","A square mark divided into tiles sits before the name.","The name is stacked in two lines of spaced capitals next to the mark."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 36
